import { createHash } from 'node:crypto';
import { AppError } from '@crew/shared';
import {verifyCredential} from '../../modules/auth/credentials.js';
export const hashToken = token => createHash('sha256').update(token).digest('hex');
export const publicUser = row => row ? {id:row.id,email:row.email,name:row.name,createdAt:row.created_at,updatedAt:row.updated_at} : null;
export function cookies(header='') {
  const result={};
  for (const item of header.split(';')) {
    const at=item.indexOf('=');
    if(at<0)continue;
    try {result[item.slice(0,at).trim()]=decodeURIComponent(item.slice(at+1));} catch {}
  }
  return result;
}
export function authenticate(ctx) {
  return (req,res,next)=>{
    try {
      req.user=null;
      req.auth=null;
      const bearer=/^Bearer (.+)$/i.exec(req.headers.authorization??'');
      if (bearer && ctx.authenticateToken) {
        const auth=ctx.authenticateToken(bearer[1]);
        if(auth){req.user=auth.user;req.auth=auth;}
      } else {
        const token=cookies(req.headers.cookie).crew_session;
        if(token&&verifyCredential(ctx.config.secret,'session',token)){
          const session=ctx.db.prepare('SELECT * FROM sessions WHERE token_hash=? AND expires_at>?').get(hashToken(token),new Date().toISOString());
          if(session){
            req.user=publicUser(ctx.db.prepare('SELECT * FROM users WHERE id=?').get(session.user_id));
            req.auth={kind:'session',sessionId:session.id,user:req.user};
            ctx.db.prepare('UPDATE sessions SET last_used_at=? WHERE id=?').run(new Date().toISOString(),session.id);
          }
        }
      }
      if(req.auth?.kind==='session'&&!['GET','HEAD','OPTIONS'].includes(req.method)&&req.headers['x-crew-request']!=='1') throw new AppError('FORBIDDEN','X-Crew-Request header is required',403);
      next();
    }catch(error){next(error);}
  };
}
export function requireAuth(req,res,next) {
  if(!req.user)return next(new AppError('UNAUTHENTICATED','Please sign in',401));
  next();
}

import {createHmac,randomBytes,timingSafeEqual} from 'node:crypto';
const purposes=new Set(['session','invite','reset','api']);
export function issueCredential(secret,purpose) {
  if(!purposes.has(purpose))throw new Error('Unknown credential purpose');
  const payload=`crew1.${purpose}.${randomBytes(32).toString('base64url')}`;
  return payload+'.'+createHmac('sha256',secret).update(payload).digest('base64url');
}
export function verifyCredential(secret,purpose,token) {
  if(!purposes.has(purpose)||typeof token!=='string'||token.length>200)return false;
  const pieces=token.split('.');
  if(pieces.length!==4||pieces[0]!=='crew1'||pieces[1]!==purpose||!/^[A-Za-z0-9_-]{43}$/.test(pieces[2])||!/^[A-Za-z0-9_-]{43}$/.test(pieces[3]))return false;
  const signature=createHmac('sha256',secret).update(pieces.slice(0,3).join('.')).digest();
  const actual=Buffer.from(pieces[3],'base64url');
  return actual.length===signature.length&&timingSafeEqual(actual,signature);
}

import { randomUUID } from 'node:crypto';
import { AppError, signupInput, loginInput } from '@crew/shared';
import {issueCredential} from './credentials.js';
import { hashPassword, verifyPassword } from './passwords.js';
import { asyncRoute } from '../../http/errors.js';
import { hashToken, publicUser, requireAuth } from '../../http/middleware/auth.js';
export function registerAuth(ctx) {
  const {app,db,bus,config}=ctx;
  function session(req,res,user) {
    const token=issueCredential(config.secret,'session');
    const time=new Date().toISOString();
    const expires=new Date(Date.now()+config.sessionDays*86400000).toISOString();
    const id=randomUUID();
    db.prepare('INSERT INTO sessions(id,user_id,token_hash,created_at,expires_at,last_used_at,user_agent) VALUES (?,?,?,?,?,?,?)').run(id,user.id,hashToken(token),time,expires,time,req.headers['user-agent']??'');
    res.cookie('crew_session',token,{httpOnly:true,sameSite:'strict',secure:false,path:'/',maxAge:config.sessionDays*86400000});
    return id;
  }
  app.post('/api/v1/auth/signup',asyncRoute(async(req,res)=>{
    const input=signupInput(req.body);
    if(db.prepare('SELECT id FROM users WHERE email=?').get(input.email))throw new AppError('CONFLICT','Email already registered',409);
    const id=randomUUID();
    const time=new Date().toISOString();
    const hash=await hashPassword(input.password);
    db.prepare('INSERT INTO users VALUES (?,?,?,?,?,?)').run(id,input.email,input.name,hash,time,time);
    const user=publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(id));
    session(req,res,user);
    bus.emit({actorId:id,entityType:'user',entityId:id,action:'created',after:user});
    res.status(201).json({user});
  }));
  app.post('/api/v1/auth/login',asyncRoute(async(req,res)=>{
    const input=loginInput(req.body);
    const row=db.prepare('SELECT * FROM users WHERE email=?').get(input.email);
    if(!row||!await verifyPassword(input.password,row.password_hash))throw new AppError('UNAUTHENTICATED','Email or password is incorrect',401);
    const user=publicUser(row);
    session(req,res,user);
    bus.emit({actorId:user.id,entityType:'user',entityId:user.id,action:'login',after:{email:user.email}});
    res.json({user});
  }));
  app.post('/api/v1/auth/logout',requireAuth,(req,res)=>{
    ctx.permissions.assertSelf(req,req.user.id,'self:write');
    if(req.auth.kind==='session')db.prepare('DELETE FROM sessions WHERE id=?').run(req.auth.sessionId);
    res.clearCookie('crew_session',{path:'/'});
    bus.emit({actorId:req.user.id,entityType:'user',entityId:req.user.id,action:'logout'});
    res.json({ok:true});
  });
  app.get('/api/v1/me',requireAuth,(req,res)=>{ctx.permissions.assertSelf(req);res.json({user:req.user,auth:{kind:req.auth.kind,scopes:req.auth.scopes??null}});});
}

import {AppError,fields,text,email} from '@crew/shared';
import {hashPassword,verifyPassword} from '../auth/passwords.js';
import {issueCredential,verifyCredential} from '../auth/credentials.js';
import {hashToken} from '../../http/middleware/auth.js';
import {securityEvent} from './security-events.js';
export const publicSession=(row,currentId)=>({id:row.id,createdAt:row.created_at,
  expiresAt:row.expires_at,lastUsedAt:row.last_used_at,userAgent:row.user_agent,current:row.id===currentId});
export function invalidateCredentials(ctx,userId,keepSessionId=null) {
  ctx.db.prepare('DELETE FROM sessions WHERE user_id=? AND id<>?').run(userId,keepSessionId??'');
  if(ctx.db.prepare("SELECT name FROM sqlite_master WHERE name='api_tokens'").get())ctx.db.prepare('UPDATE api_tokens SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL').run(ctx.now(),userId);
}
export function registerAccount(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/auth/sessions',requireAuth,(req,res)=>{
    p.assertSelf(req);
    const rows=db.prepare('SELECT * FROM sessions WHERE user_id=? AND expires_at>? ORDER BY created_at DESC,id').all(req.user.id,ctx.now());
    res.json(ctx.paginate(rows.map(row=>publicSession(row,req.auth.sessionId)),req.query));
  });
  app.delete('/api/v1/auth/sessions/:sessionId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');
    const row=db.prepare('SELECT * FROM sessions WHERE id=? AND user_id=?').get(req.params.sessionId,req.user.id);
    if(!row)throw new AppError('NOT_FOUND','Session not found',404);
    db.prepare('DELETE FROM sessions WHERE id=?').run(row.id);
    if(row.id===req.auth.sessionId)res.clearCookie('crew_session',{path:'/'});
    securityEvent(ctx,req,'session',row.id,'revoked',{before:publicSession(row,req.auth.sessionId)});
    res.json({ok:true,current:row.id===req.auth.sessionId});
  });
  app.post('/api/v1/auth/sessions/revoke-others',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');fields(req.body,[]);
    const result=db.prepare('DELETE FROM sessions WHERE user_id=? AND id<>?').run(req.user.id,req.auth.sessionId??'');
    securityEvent(ctx,req,'user',req.user.id,'sessions_revoked',{after:{count:Number(result.changes)}});
    res.json({revoked:Number(result.changes)});
  });
  app.post('/api/v1/auth/password/change',requireAuth,ctx.asyncRoute(async(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');fields(req.body,['currentPassword','password']);
    const currentPassword=text(req.body.currentPassword,'currentPassword',{max:1024,trim:false});
    const password=text(req.body.password,'password',{min:10,max:1024,trim:false});
    const user=db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);
    if(!await verifyPassword(currentPassword,user.password_hash))throw new AppError('VALIDATION','Current password is incorrect',422,{currentPassword:'Current password is incorrect'});
    if(currentPassword===password)throw new AppError('VALIDATION','Choose a different password',422,{password:'Must differ from your current password'});
    const hash=await hashPassword(password);
    ctx.transaction(()=>{
      db.prepare('UPDATE users SET password_hash=?,updated_at=? WHERE id=?').run(hash,ctx.now(),req.user.id);
      invalidateCredentials(ctx,req.user.id,req.auth.sessionId);
      db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND used_at IS NULL AND revoked_at IS NULL').run(ctx.now(),req.user.id);
    });
    securityEvent(ctx,req,'user',req.user.id,'password_changed',{after:{otherSessionsRevoked:true,apiTokensRevoked:true}});
    res.json({ok:true,signInRequired:req.auth.kind!=='session'});
  }));
  app.post('/api/v1/auth/password/reset/request',(req,res)=>{
    fields(req.body,['email']);const address=email(req.body.email);
    const user=db.prepare('SELECT * FROM users WHERE email=?').get(address);
    if(user){
      const token=issueCredential(ctx.config.secret,'reset'),id=ctx.id(),time=ctx.now();
      const expiresAt=new Date(Date.now()+3600000).toISOString();
      ctx.transaction(()=>{
        db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND used_at IS NULL AND revoked_at IS NULL').run(time,user.id);
        db.prepare('INSERT INTO password_resets(id,user_id,token_hash,created_at,expires_at) VALUES (?,?,?,?,?)').run(id,user.id,hashToken(token),time,expiresAt);
        const link=ctx.config.baseUrl.replace(/\/$/,'')+'/#/reset?token='+encodeURIComponent(token);
        ctx.enqueueOutbox({userId:user.id,kind:'reset',toEmail:user.email,subject:'Reset your Crew password',textBody:'Reset your password: '+link,payload:{resetId:id,link,expiresAt}});
      });
      securityEvent(ctx,null,'user',user.id,'password_reset_requested',{actorId:user.id,after:{expiresAt}});
    }
    res.status(202).json({ok:true,message:'If the account exists, a reset link is in its outbox.'});
  });
  app.post('/api/v1/auth/password/reset',ctx.asyncRoute(async(req,res)=>{
    fields(req.body,['token','password']);
    const token=text(req.body.token,'token',{max:200});
    const password=text(req.body.password,'password',{min:10,max:1024,trim:false});
    if(!verifyCredential(ctx.config.secret,'reset',token))throw new AppError('VALIDATION','Reset link is invalid or expired',422,{token:'Request a new reset link'});
    const reset=db.prepare('SELECT * FROM password_resets WHERE token_hash=?').get(hashToken(token));
    if(!reset||reset.used_at||reset.revoked_at||reset.expires_at<=ctx.now())throw new AppError('VALIDATION','Reset link is invalid or expired',422,{token:'Request a new reset link'});
    const hash=await hashPassword(password);
    ctx.transaction(()=>{
      const current=db.prepare('SELECT * FROM password_resets WHERE id=?').get(reset.id);
      if(current.used_at||current.revoked_at||current.expires_at<=ctx.now())throw new AppError('CONFLICT','Reset link has already been used or expired',409);
      db.prepare('UPDATE users SET password_hash=?,updated_at=? WHERE id=?').run(hash,ctx.now(),reset.user_id);
      db.prepare('UPDATE password_resets SET used_at=? WHERE id=?').run(ctx.now(),reset.id);
      db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND id<>? AND used_at IS NULL AND revoked_at IS NULL').run(ctx.now(),reset.user_id,reset.id);
      invalidateCredentials(ctx,reset.user_id);
    });
    res.clearCookie('crew_session',{path:'/'});
    securityEvent(ctx,null,'user',reset.user_id,'password_reset',{actorId:reset.user_id,after:{allSessionsRevoked:true,apiTokensRevoked:true}});
    res.json({ok:true,signInRequired:true});
  }));
}

import {AppError,inviteInput,fields,text,choice} from '@crew/shared';
import {hashToken} from '../../http/middleware/auth.js';
import {issueCredential,verifyCredential} from '../auth/credentials.js';
import {securityEvent} from './security-events.js';
export function invitationState(row,time=new Date().toISOString()) {
  return row.accepted_at?'accepted':row.revoked_at?'revoked':row.expires_at<=time?'expired':'pending';
}
export const publicInvitation=row=>({id:row.id,orgId:row.org_id,email:row.email,role:row.role,
  projectIds:JSON.parse(row.project_ids_json),createdBy:row.created_by,createdAt:row.created_at,
  expiresAt:row.expires_at,acceptedAt:row.accepted_at,acceptedBy:row.accepted_by,
  revokedAt:row.revoked_at,state:invitationState(row)});
export function registerInvitations(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  function row(id) {
    const found=db.prepare('SELECT * FROM invitations WHERE id=?').get(id);
    if(!found)throw new AppError('NOT_FOUND','Invitation not found',404);
    return found;
  }
  function pending(token) {
    if(!verifyCredential(ctx.config.secret,'invite',token))throw new AppError('NOT_FOUND','Invitation link is invalid',404);
    const found=db.prepare('SELECT * FROM invitations WHERE token_hash=?').get(hashToken(token));
    if(!found)throw new AppError('NOT_FOUND','Invitation link is invalid',404);
    const state=invitationState(found);
    if(state!=='pending')throw new AppError('CONFLICT','Invitation is '+state,409,{token:'This invitation is '+state});
    return found;
  }
  function validateProjects(orgId,role,ids) {
    if(role!=='guest'&&ids.length)throw new AppError('VALIDATION','Project grants are only for guests',422,{projectIds:'Only guest invitations can grant projects'});
    for(const id of ids) {
      const project=db.prepare('SELECT org_id FROM projects WHERE id=?').get(id);
      if(!project||project.org_id!==orgId)throw new AppError('VALIDATION','Project must belong to this organization',422,{projectIds:'Choose projects in this organization'});
    }
  }
  app.get('/api/v1/orgs/:orgId/invitations',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'invites:manage');
    const state=req.query.state?choice(req.query.state,'state',['pending','accepted','revoked','expired','all']):'all';
    const items=db.prepare('SELECT * FROM invitations WHERE org_id=? ORDER BY created_at DESC,id').all(req.params.orgId)
      .map(publicInvitation).filter(item=>state==='all'||item.state===state);
    res.json(ctx.paginate(items,req.query));
  });
  app.post('/api/v1/orgs/:orgId/invitations',requireAuth,(req,res)=>{
    const {orgId}=req.params;
    const actor=p.assertOrg(req,orgId,'invites:manage');
    const input=inviteInput(req.body);
    if(input.role==='owner'&&actor.role!=='owner')throw new AppError('FORBIDDEN','Only owners can invite another owner',403);
    validateProjects(orgId,input.role,input.projectIds);
    const existing=db.prepare('SELECT id FROM users WHERE email=?').get(input.email);
    if(existing&&p.membership(existing.id,orgId))throw new AppError('CONFLICT','Recipient is already a member',409,{email:'Already in this organization'});
    if(db.prepare('SELECT id FROM invitations WHERE org_id=? AND email=? AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>?').get(orgId,input.email,ctx.now()))throw new AppError('CONFLICT','A pending invitation already exists',409,{email:'Revoke the pending invitation first'});
    const id=ctx.id(),time=ctx.now(),token=issueCredential(ctx.config.secret,'invite');
    const expiresAt=new Date(Date.now()+input.expiresInHours*3600000).toISOString();
    const organization=db.prepare('SELECT name FROM organizations WHERE id=?').get(orgId);
    const invitation=ctx.transaction(()=>{
      db.prepare('INSERT INTO invitations(id,org_id,email,role,token_hash,project_ids_json,created_by,created_at,expires_at) VALUES (?,?,?,?,?,?,?,?,?)')
        .run(id,orgId,input.email,input.role,hashToken(token),JSON.stringify(input.projectIds),req.user.id,time,expiresAt);
      const link=ctx.config.baseUrl.replace(/\/$/,'')+'/#/invitations/accept?token='+encodeURIComponent(token);
      ctx.enqueueOutbox({orgId,userId:existing?.id??null,kind:'invite',toEmail:input.email,
        subject:'Invitation to '+organization.name,textBody:`Join ${organization.name} as ${input.role}: ${link}`,
        payload:{invitationId:id,link,expiresAt}});
      return publicInvitation(row(id));
    });
    securityEvent(ctx,req,'invitation',id,'created',{orgId,after:invitation});
    res.status(201).json({invitation});
  });
  app.post('/api/v1/invitations/preview',(req,res)=>{
    fields(req.body,['token']);
    const found=pending(text(req.body.token,'token',{max:200}));
    const organization=db.prepare('SELECT name FROM organizations WHERE id=?').get(found.org_id);
    res.json({invitation:{...publicInvitation(found),organizationName:organization.name}});
  });
  app.post('/api/v1/invitations/accept',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');fields(req.body,['token']);
    const found=pending(text(req.body.token,'token',{max:200}));
    if(req.user.email.toLowerCase()!==found.email.toLowerCase())throw new AppError('FORBIDDEN','Sign in with the invited email address',403,{email:'The invitation belongs to another account'});
    if(p.membership(req.user.id,found.org_id))throw new AppError('CONFLICT','Account is already an organization member',409);
    const projectIds=JSON.parse(found.project_ids_json);
    validateProjects(found.org_id,found.role,projectIds);
    const time=ctx.now();
    const invitation=ctx.transaction(()=>{
      db.prepare('INSERT INTO memberships VALUES (?,?,?,?,?)').run(found.org_id,req.user.id,found.role,time,time);
      for(const projectId of projectIds)db.prepare('INSERT INTO project_guests VALUES (?,?,?)').run(projectId,req.user.id,time);
      db.prepare('UPDATE invitations SET accepted_at=?,accepted_by=? WHERE id=?').run(time,req.user.id,found.id);
      return publicInvitation(row(found.id));
    });
    securityEvent(ctx,req,'invitation',found.id,'accepted',{orgId:found.org_id,before:publicInvitation(found),after:invitation});
    securityEvent(ctx,req,'organization',req.user.id,'member_added',{orgId:found.org_id,after:{userId:req.user.id,role:found.role}});
    for(const projectId of projectIds)securityEvent(ctx,req,'project',projectId,'guest_added',{orgId:found.org_id,projectId,after:{userId:req.user.id}});
    res.json({invitation,membership:{orgId:found.org_id,userId:req.user.id,role:found.role}});
  });
  app.delete('/api/v1/invitations/:invitationId',requireAuth,(req,res)=>{
    const found=row(req.params.invitationId);const actor=p.assertOrg(req,found.org_id,'invites:manage');
    if(found.role==='owner'&&actor.role!=='owner')throw new AppError('FORBIDDEN','Only owners can manage owner invitations',403);
    if(invitationState(found)!=='pending')throw new AppError('CONFLICT','Only pending invitations can be revoked',409);
    db.prepare('UPDATE invitations SET revoked_at=? WHERE id=?').run(ctx.now(),found.id);
    const invitation=publicInvitation(row(found.id));
    securityEvent(ctx,req,'invitation',found.id,'revoked',{orgId:found.org_id,before:publicInvitation(found),after:invitation});
    res.json({invitation});
  });
}

import {choice} from '@crew/shared';
import {publicOutbox} from './outbox.js';
export function registerOutbox(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/me/outbox',requireAuth,(req,res)=>{
    p.assertSelf(req);
    const kind=req.query.kind?choice(req.query.kind,'kind',['invite','reset','digest']):null;
    const rows=db.prepare('SELECT * FROM outbox WHERE to_email=? AND (user_id IS NULL OR user_id=?) ORDER BY created_at DESC,id').all(req.user.email,req.user.id);
    res.json(ctx.paginate(rows.filter(row=>!kind||row.kind===kind).map(publicOutbox),req.query));
  });
  app.get('/api/v1/orgs/:orgId/outbox',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'invites:manage');
    const rows=db.prepare("SELECT * FROM outbox WHERE org_id=? AND kind='invite' ORDER BY created_at DESC,id").all(req.params.orgId);
    res.json(ctx.paginate(rows.map(publicOutbox),req.query));
  });
}

import {registerInvitations} from './invitations.js';
import {registerAccount} from './account.js';
import {registerOutbox} from './outbox-routes.js';
import {createPermissions} from '../../http/middleware/permissions.js';
import {registerOrganizations} from './orgs.js';
import {registerTeams} from './teams.js';
import {enqueueOutbox} from './outbox.js';
export function registerRoutes(ctx) {
  ctx.permissions=createPermissions(ctx);
  ctx.enqueueOutbox=input=>enqueueOutbox(ctx,input);
  registerOrganizations(ctx);
  registerTeams(ctx);
  registerInvitations(ctx);
  registerAccount(ctx);
  registerOutbox(ctx);
}
